"""The Unseen Archive - Kaggle runner. GENERATED by `unseen kaggle-bench`; do not edit the copy on Kaggle.

Runs inside a Kaggle GPU session (standard library only, any Python 3.10+):
  1. records the machine (GPU, driver, RAM, disk)
  2. clones the project from GitHub at the exact commit the local machine is on
  3. installs uv, the app, and the pinned ComfyUI runtime (same code path as on Windows)
  4. downloads and sha256-verifies the model set
  5. runs `unseen bench-video` with the requested model/phases/preset
  6. copies results (clips, reports, contact sheets; not raw frames) to /kaggle/working
It always exits 0 and writes /kaggle/working/job_summary.json, so the local side can report
exactly which step failed and why.
"""

import json
import os
import shutil
import subprocess
import sys
import time
import traceback
from pathlib import Path

JOB = json.loads(r"""__JOB_JSON__""")

OUT = Path("/kaggle/working")
ROOT = Path("/tmp/unseen")
APP = ROOT / "app"
OUT.mkdir(parents=True, exist_ok=True)
LOG_FH = open(OUT / "runner.log", "a", encoding="utf-8", errors="replace")
SUMMARY = {"job": JOB, "status": "running", "steps": [], "env": {}, "started_at": time.time()}


def log(msg):
    line = f"[{time.strftime('%H:%M:%S')}] {msg}"
    print(line, flush=True)
    LOG_FH.write(line + "\n")
    LOG_FH.flush()


def save():
    SUMMARY["updated_at"] = time.time()
    (OUT / "job_summary.json").write_text(json.dumps(SUMMARY, indent=2), encoding="utf-8")


def run(cmd, cwd=None, env=None, capture=False):
    log("$ " + " ".join(str(c) for c in cmd))
    proc = subprocess.Popen([str(c) for c in cmd], cwd=cwd, env=env, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True, errors="replace")
    tail, lines = [], []
    for line in proc.stdout:
        print(line, end="", flush=True)
        LOG_FH.write(line)
        tail = (tail + [line])[-80:]
        if capture:
            lines.append(line)
    LOG_FH.flush()
    rc = proc.wait()
    if rc != 0:
        raise RuntimeError(f"exit code {rc}: {' '.join(str(c) for c in cmd)}\n" + "".join(tail))
    return "".join(lines)


def step(name, fn):
    log(f"===== {name}")
    entry = {"name": name, "ok": False}
    t0 = time.time()
    try:
        fn()
        entry["ok"] = True
    except Exception as exc:
        entry["error"] = str(exc)[-6000:]
        raise
    finally:
        entry["seconds"] = round(time.time() - t0, 1)
        SUMMARY["steps"].append(entry)
        save()


def app_env():
    env = dict(os.environ)
    env["PYTHONUNBUFFERED"] = "1"
    env["UV_LINK_MODE"] = "copy"
    env.pop("PYTHONPATH", None)   # Kaggle's site packages must not leak into our venvs
    return env


def uv():
    exe = shutil.which("uv") or str(Path(sys.executable).parent / "uv")
    return exe


def collect_env():
    def sh(cmd):
        try:
            return subprocess.run(cmd, capture_output=True, text=True, timeout=60).stdout.strip()
        except Exception as exc:
            return repr(exc)
    SUMMARY["env"] = {
        "python": sys.version.split()[0],
        "nvidia_smi": sh(["nvidia-smi", "--query-gpu=name,memory.total,driver_version", "--format=csv,noheader"]),
        "driver_cuda": sh(["bash", "-c", "nvidia-smi | grep -o 'CUDA Version: [0-9.]*'"]),
        "ram": sh(["bash", "-c", "free -g | head -2"]),
        "disk_tmp": sh(["df", "-h", "/tmp"]),
        "disk_working": sh(["df", "-h", str(OUT)]),
        "cpus": os.cpu_count(),
    }
    log(json.dumps(SUMMARY["env"], indent=2))


def ensure_ffmpeg():
    if shutil.which("ffmpeg") and shutil.which("ffprobe"):
        log("ffmpeg present")
        return
    run(["bash", "-c", "apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq ffmpeg"])


def install_uv():
    run([sys.executable, "-m", "pip", "install", "-q", "--upgrade", "uv"])
    run([uv(), "--version"])


def clone():
    if APP.exists():
        shutil.rmtree(APP)
    ROOT.mkdir(parents=True, exist_ok=True)
    run(["git", "clone", "--filter=blob:none", "--no-checkout", JOB["repo_url"], APP])
    run(["git", "-c", "advice.detachedHead=false", "checkout", "--detach", JOB["commit"]], cwd=APP)


def unseen(*args):
    run([uv(), "run", "--no-dev", "unseen", *args], cwd=APP, env=app_env())


def app_sync():
    run([uv(), "sync", "--no-dev"], cwd=APP, env=app_env())


def bench():
    args = ["bench-video", "--model", JOB["model"], "--phases", JOB["phases"]]
    if JOB.get("preset"):
        args += ["--preset", JOB["preset"]]
    if JOB.get("mode"):
        args += ["--mode", JOB["mode"]]
    if JOB.get("timeout_min"):
        args += ["--timeout-min", str(JOB["timeout_min"])]
    unseen(*args)


def collect_results():
    src = APP / "bench_results"
    dst = OUT / "bench_results"
    if not src.is_dir():
        log("no bench_results produced")
        return
    shutil.copytree(src, dst, dirs_exist_ok=True,
                    ignore=shutil.ignore_patterns("frames", "compare.html"))
    log(f"copied results to {dst}")


def main():
    save()
    try:
        step("environment", collect_env)
        step("ffmpeg", ensure_ffmpeg)
        step("install uv", install_uv)
        step("clone project @ " + JOB["commit"][:10], clone)
        step("app environment", app_sync)
        step("ComfyUI runtime", lambda: unseen("setup-comfy"))
        step("models: " + JOB["model_set"], lambda: unseen("fetch-models", "--set", JOB["model_set"]))
        step("benchmark", bench)
        SUMMARY["status"] = "ok"
    except Exception:
        SUMMARY["status"] = "failed"
        SUMMARY["traceback"] = traceback.format_exc()[-6000:]
        log(SUMMARY["traceback"])
    finally:
        try:
            collect_results()
        except Exception as exc:
            SUMMARY["collect_error"] = repr(exc)
        SUMMARY["finished_at"] = time.time()
        save()
        log(f"UNSEEN_JOB_DONE status={SUMMARY['status']}")


main()
